202: export function runSort(board: SortBoard, program: Block[]): Omit<RunResult, "blocksUsed"> {
203:   const frames: SortFrame[] = [];
204:   let tooLong = false;
205: 
206:   board.items.forEach((item, itemIndex) => {
207:     let box = null as string | null;
208:     let steps = 0;
209:     const trail: string[] = [];
210:     const exec = (blocks: Block[]): boolean => {
211:       for (const b of blocks) {
212:         if (box !== null) return false;
213:         if (++steps > MAX_STEPS) {
214:           tooLong = true;
215:           return false;
216:         }
217:         trail.push(b.id);
218:         if (b.type === "put") {
219:           box = b.box;
220:           return false;
221:         }
222:         if (b.type === "if") {
223:           const branch = item.tags.includes(b.cond) ? b.then : b.else;
224:           if (!exec(branch)) return false;
225:         }
226:         if (b.type === "repeat") {
227:           for (let i = 0; i < b.times; i++) if (!exec(b.body)) return false;
228:         }
229:       }
230:       return true;
231:     };
232:     exec(program);
233:     frames.push({ itemIndex, box, correct: box === item.answer, trail });
234:   });
235: 
236:   if (tooLong) return { success: false, reason: "too-long", sortFrames: frames };
237:   const firstBad = frames.find((f) => !f.correct);
238:   if (firstBad) {
239:     const item = board.items[firstBad.itemIndex];
240:     return {
241:       success: false,
242:       reason: firstBad.box === null ? "no-box" : "wrong-box",
243:       detail: item.label,
