"// Web Speech API text-to-speech helper for Bibi AI (FR-AI-06).
// Allows children with emerging literacy to hear Bibi's guidance out loud.

export function isSpeechSupported(): boolean {
  return typeof window !== "undefined" && "speechSynthesis" in window;
}

export function cleanTextForSpeech(text: string): string {
  return text
    // Remove markdown formatting
    .replace(/[*_#`~>]/g, "")
    // Remove URLs
    .replace(/https?:\/\/\S+/g, "")
    // Remove emojis so the speech engine doesn't read out emoji descriptions
    .replace(/[\u{1F300}-\u{1F9FF}\u{1FA00}-\u{1FAFF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, "")
    // Remove leftover symbols and collapse whitespace
    .replace(/\s+/g, " ")
    .trim();
}

let activeUtterance: SpeechSynthesisUtterance | null = null;

export function stopSpeaking() {
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
    } catch {
      // Ignore cancel errors
    }
  }
  activeUtterance = null;
}

export function speakBibiText(
  text: string,
  callbacks?: {
    onStart?: () => void;
    onEnd?: () => void;
    onError?: (err: unknown) => void;
  }
) {
  if (!isSpeechSupported()) {
    callbacks?.onEnd?.();
    return;
  }

  stopSpeaking();

  const cleaned = cleanTextForSpeech(text);
  if (!cleaned) {
    callbacks?.onEnd?.();
    return;
  }

  const utterance = new SpeechSynthesisUtterance(cleaned);
  activeUtterance = utterance;

  // Mascot voice personality: friendly, cheerful, slightly higher pitch, gentle pacing for kids
  utterance.pitch = 1.15;
  utterance.rate = 0.95;

  const voices = window.speechSynthesis.getVoices();
  const idVoice = voices.find(
    (v) =>
      v.lang.toLowerCase().startsWith("id") ||
      v.lang.toLowerCase().includes("id-id") ||
      v.name.toLowerCase().includes("indonesia")
  );

